import unittest
from count import count_active

class CountTests(unittest.TestCase):
    def test_enabled(self):
        self.assertEqual(count_active([{"enabled": True}, {"enabled": False}]), 1)
    def test_cancelled(self):
        self.assertEqual(count_active([{"enabled": True, "cancelled": True}]), 0)
    def test_default(self):
        self.assertEqual(count_active([{"enabled": True}, {"enabled": True, "cancelled": False}]), 2)

